use vstd::prelude::*;

verus! {
    /// Multiply a polynomial by X: given coefficients c,
    /// return [0.0, c[0], c[1], …, c[n−1]].
    fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
        ensures
            // the result is exactly one entry longer
            result.len() == c.len() + 1,
            // the 0th entry is 0.0
            result.index(0) == 0.0,
            // for each original coefficient c[i], it appears at result[i+1]
            forall |i: nat| i < c.len() ==> result.index(i+1) == c.index(i),
    {
        let mut result = Vec::with_capacity(c.len() + 1);
        // push the leading zero
        result.push(0.0);

        let mut i: usize = 0;
        while i < c.len()
            invariant
                // i walks from 0 up to c.len()
                i <= c.len(),
                // at loop‐entry, result.len() == i+1
                result.len() == i + 1,
                // the 0th entry remains 0.0
                result.index(0) == 0.0,
                // all the shifted entries up to i have been filled correctly
                forall |j: nat|
                    j < i ==>
                        result.index(j+1) == c.index(j),
            decreases
                // this loop obviously terminates
                c.len() - i,
        {
            // push the next coefficient
            result.push(c[i]);
            // record that indeed the newly pushed element is in the right place
            assert(result.index(i + 1) == c.index(i));
            i += 1;
        }

        result
    }
}

